export type Selection = {
	key: string,
	color: RGB,
	selector: Selector,
};

/**  An edit of the selection tree as asked for: a saved selection to add, or a plain edit. */
export type SelectionEdit = 
/**  Add a saved selection's parts, with its value names resolved against the open map. */
{ kind: "addSaved"; id: string } | 
/**  Any other edit of the selection tree. */
SelectionOp;

export type SelectionInput = {
	selector: Selector<SelectionInput>,
	color?: RGB | null,
};

export type SelectionOp = { kind: "add"; selections: SelectionInput[] } | { kind: "set"; selections: SelectionInput[] } | { kind: "remove"; keys: string[] } | { kind: "toggle"; selections: SelectionInput[] } | { kind: "manual"; id: number } | { kind: "active"; op: SelectionOp } | 
/**  Join the listed selections named by `keys`, or every one when null, into one group. */
{ kind: "combine"; group: Group; keys: string[] | null } | 
/**
 *  Replace the listed selections named by `keys`, or every one when null, with the
 *  locations none of them selects.
 */
{ kind: "complement"; keys: string[] | null } | { kind: "ghost"; index: number } | { kind: "isolate"; index: number } | { kind: "ghostAll" } | { kind: "invert"; path: number[] } | { kind: "compose"; drag: number[]; drop: number[]; group: Group } | { kind: "move"; from: number[]; to: number[]; place: Place } | { kind: "removeAt"; path: number[] } | { kind: "replace"; path: number[]; selection: SelectionInput } | { kind: "color"; path: number[]; color: RGB } | { kind: "polygonName"; path: number[]; name: string };

/**  Selection predicates and composites, serialized with a `type` discriminator. */
export type Selector<S = Selection> = { type: "Locations"; locations: number[]; name: string | null } | { type: "Everything" } | 
/**  The locations currently selected in the editor. */
{ type: "Selected" } | { type: "Polygon"; polygon: PolygonGeometry } | { type: "Uncommitted" } | { type: "Manual"; locations: number[] } | { type: "Duplicates"; distance: number } | { type: "Validation"; locations: number[]; category: string } | { type: "Reviewed"; locations: number[]; sessionId: string; mode: ReviewMode } | { type: "Intersection"; selections: S[] } | { type: "Union"; selections: S[] } | { type: "Invert"; selections: S[] } | { type: "Filter"; field: string; test: FilterOp } | 
/**
 *  Rank by a field expression, optionally keeping only the first `k`.
 *  Unscorable locations rank last; without `k`, all child locations are kept.
 */
{ type: "Ranked"; 
/**  What to rank; `null` ranks the whole map. */
selection: S | null; expr: string; k: number | null; ascending: boolean } | 
/**  `n` locations of a selection drawn uniformly at random, without replacement. */
{ type: "Sample"; 
/**  What to draw from; `null` draws from the whole map. */
selection: S | null; n: number } | 
/**  A selection thinned to a spread-out subset. */
{ type: "Spaced"; 
/**  What to thin; `null` thins the whole map. */
selection: S | null; thin: Thinning } | 
/**  A selection thinned on a honeycomb, never two picks closer than half the spacing. */
{ type: "EvenlySpaced"; 
/**  What to thin; `null` thins the whole map. */
selection: S | null; thin: Thinning } | 
/**  The locations of a selection within `radiusM` metres of a coordinate. */
{ type: "Nearby"; 
/**  Where to look; `null` looks over the whole map. */
selection: S | null; lat: number; lng: number; radiusM: number } | 
/**  The location of a selection closest to a coordinate. */
{ type: "Nearest"; 
/**  Where to look; `null` looks over the whole map. */
selection: S | null; lat: number; lng: number };

/**  How a session's connection stands. */
export type SessionLink = 
/**  Waiting for the host to come online. */
{ state: "waiting" } | 
/**  Connecting to the host. */
{ state: "connecting" } | 
/**  Connected, and receiving the map from the host. */
{ state: "syncing" } | 
/**  Connected. */
{ state: "live" } | 
/**  The connection dropped and is being made again. */
{ state: "reconnecting" } | 
/**  The session is over, and why. */
{ state: "ended"; reason: string };

/**  Operations computed over the selected locations as a group. */
export type SetOp = 
/**
 *  Merge each group into its best-scored location, which keeps its id and takes in the
 *  others' list values and extra fields.
 */
{ kind: "merge"; groups: number[][]; score: string | null } | 
/**
 *  Remove duplicates within `distance` metres of each other, keeping the best-scored
 *  survivor per cluster.
 */
{ kind: "pruneDuplicates"; distance: number; score: string | null };

